<?php
session_start();
if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32));
$username = $_SESSION['username'] ?? null;
$avatar = '⌨️';
$csrf = $_SESSION['csrf'];
$stats = ['wins' => 0, 'losses' => 0, 'games_played' => 0];
if ($username) {
    try {
        require_once __DIR__ . '/db.php';
        $pdo = database();
        $find = $pdo->prepare('SELECT id, avatar FROM users WHERE username = ?');
        $find->execute([$username]);
        $profile = $find->fetch();
        $id = (int)($profile['id'] ?? 0);
        $avatar = $profile['avatar'] ?? $avatar;
        if ($id) {
            $query = $pdo->prepare('SELECT wins, losses, games_played FROM online_stats WHERE user_id = ?');
            $query->execute([$id]);
            $stats = $query->fetch() ?: $stats;
        }
    } catch (Throwable $e) { }
}
?>
